<?php

declare(strict_types=1);

namespace DDD\Domain\Common\Entities\MediaItems;

/**
 * How AI took part in making an image: generated by a model, a real image edited with one, or not AI. Labels and the
 * machine-readable tag of an image ({@see AIImageIptcTag}, the AI badge) are decided on it.
 *
 * Holds constants only, is never serialized or persisted, and is therefore not a DDD value object.
 */
class AIImageKind
{
    /** @var string A generative model made the image */
    public const string GENERATED = 'GENERATED';

    /** @var string A real image, edited with a generative model */
    public const string EDITED = 'EDITED';

    /** @var string No generative model made or changed the image */
    public const string NOT_AI = 'NOT_AI';

    /** @var string[] Every AI image kind */
    public const array ALL_KINDS = [
        self::GENERATED,
        self::EDITED,
        self::NOT_AI,
    ];

    /** @var string[] The kinds that carry an AI mark */
    public const array AI_KINDS = [
        self::GENERATED,
        self::EDITED,
    ];

    /**
     * Whether $aiImageKind is one of {@see self::ALL_KINDS}; null and any other string are not.
     */
    public static function isKnownAIImageKind(?string $aiImageKind): bool
    {
        return in_array($aiImageKind, self::ALL_KINDS, true);
    }

    /**
     * Whether $aiImageKind is a kind a generative model took part in ({@see self::AI_KINDS}).
     */
    public static function isAIKind(?string $aiImageKind): bool
    {
        return in_array($aiImageKind, self::AI_KINDS, true);
    }
}
